// face was hit and pushes the ball out of the brick so it can't stick.
// Returns true if a bounce was applied.
export function hitBrick(ball, brick) {
  const penX = min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const penY = min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

